PRAGMA foreign_keys = ON;

-- UTC events.
CREATE TABLE "event" (
  "at" TEXT NOT NULL PRIMARY KEY DEFAULT '2000-02-29T23:59:59Z' CHECK ("at" IS NULL OR (typeof("at") = 'text' AND length("at") = 20 AND instr("at", char(0)) = 0 AND "at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("at", 1, 4) BETWEEN '0001' AND '9999' AND substr("at", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("at", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("at", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("at", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("at", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("at", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END AND substr("at", 12, 2) BETWEEN '00' AND '23' AND substr("at", 15, 2) BETWEEN '00' AND '59' AND substr("at", 18, 2) BETWEEN '00' AND '59')),
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')) CHECK ("created_at" IS NULL OR (typeof("created_at") = 'text' AND length("created_at") = 20 AND instr("created_at", char(0)) = 0 AND "created_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("created_at", 1, 4) BETWEEN '0001' AND '9999' AND substr("created_at", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("created_at", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("created_at", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("created_at", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("created_at", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("created_at", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END AND substr("created_at", 12, 2) BETWEEN '00' AND '23' AND substr("created_at", 15, 2) BETWEEN '00' AND '59' AND substr("created_at", 18, 2) BETWEEN '00' AND '59')),
  "optional" TEXT DEFAULT NULL CHECK ("optional" IS NULL OR (typeof("optional") = 'text' AND length("optional") = 20 AND instr("optional", char(0)) = 0 AND "optional" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("optional", 1, 4) BETWEEN '0001' AND '9999' AND substr("optional", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("optional", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("optional", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("optional", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("optional", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("optional", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END AND substr("optional", 12, 2) BETWEEN '00' AND '23' AND substr("optional", 15, 2) BETWEEN '00' AND '59' AND substr("optional", 18, 2) BETWEEN '00' AND '59')),
  "raw" TEXT NOT NULL DEFAULT ('0001-01-01T00:00:00Z') CHECK ("raw" IS NULL OR (typeof("raw") = 'text' AND length("raw") = 20 AND instr("raw", char(0)) = 0 AND "raw" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("raw", 1, 4) BETWEEN '0001' AND '9999' AND substr("raw", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("raw", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("raw", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("raw", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("raw", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("raw", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END AND substr("raw", 12, 2) BETWEEN '00' AND '23' AND substr("raw", 15, 2) BETWEEN '00' AND '59' AND substr("raw", 18, 2) BETWEEN '00' AND '59')),
  "now" TEXT NOT NULL DEFAULT 'contextual identifier'
) STRICT;

CREATE TABLE "pair" (
  "start" TEXT NOT NULL CHECK ("start" IS NULL OR (typeof("start") = 'text' AND length("start") = 20 AND instr("start", char(0)) = 0 AND "start" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("start", 1, 4) BETWEEN '0001' AND '9999' AND substr("start", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("start", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("start", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("start", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("start", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("start", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END AND substr("start", 12, 2) BETWEEN '00' AND '23' AND substr("start", 15, 2) BETWEEN '00' AND '59' AND substr("start", 18, 2) BETWEEN '00' AND '59')),
  "end" TEXT NOT NULL CHECK ("end" IS NULL OR (typeof("end") = 'text' AND length("end") = 20 AND instr("end", char(0)) = 0 AND "end" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("end", 1, 4) BETWEEN '0001' AND '9999' AND substr("end", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("end", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("end", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("end", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("end", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("end", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END AND substr("end", 12, 2) BETWEEN '00' AND '23' AND substr("end", 15, 2) BETWEEN '00' AND '59' AND substr("end", 18, 2) BETWEEN '00' AND '59')),
  PRIMARY KEY ("start", "end")
) STRICT;
